## tests/test_submission_verdict_wired.py
```python
"""Wired RED oracle for ngv2/submission_verdict.py (Phase 7.1 verdict ingester).

Pinned contract:

- ``SubmissionVerdict`` dataclass: fields ``submission_id`` (required, non-empty),
  ``state`` (default 'submitted'; one of VERDICT_STATES), ``payout`` (float, default
  0.0), ``reason`` (str), ``raw`` (dict). ``to_dict``/``from_dict`` round-trip;
  ``validate()`` raises ValueError on empty id or unknown state; ``is_accepted`` /
  ``is_rejected`` properties (rejected covers 'rejected' and 'duplicate').
- VERDICT_STATES includes at least submitted/triage/accepted/rejected/duplicate.
- ``parse_verdict_response(submission_id, response)`` is PURE: maps a raw response
  mapping (state|status, payout|amount, reason|message) to a SubmissionVerdict;
  unknown/absent state falls back to 'submitted'; non-dict response tolerated.
- ``ingest_verdict(submission_id, fetcher)`` polls via the INJECTED ``fetcher``
  seam ONLY (hermetic — no real network), returns a validated SubmissionVerdict.
"""
import pytest

from ngv2.submission_verdict import (
    SubmissionVerdict,
    VERDICT_STATES,
    parse_verdict_response,
    ingest_verdict,
)


def test_states_enum_covers_lifecycle():
    assert set(VERDICT_STATES) >= {
        "submitted", "triage", "accepted", "rejected", "duplicate"}


def test_ingest_parses_accepted_with_payout_and_is_hermetic():
    calls = []

    def fetcher(sid):
        calls.append(sid)
        return {"status": "accepted", "amount": 500, "message": "nice find"}

    v = ingest_verdict("sub-1", fetcher)
    assert v.submission_id == "sub-1"
    assert v.state == "accepted"
    assert v.is_accepted is True
    assert v.is_rejected is False
    assert v.payout == 500.0
    assert v.reason == "nice find"
    # hermetic: only the injected fetcher was consulted, exactly once
    assert calls == ["sub-1"]


def test_ingest_rejected_and_duplicate_are_rejections():
    assert ingest_verdict("s", lambda _i: {"state": "rejected"}).is_rejected
    assert ingest_verdict("s", lambda _i: {"state": "duplicate"}).is_rejected
    assert not ingest_verdict("s", lambda _i: {"state": "triage"}).is_rejected


def test_unknown_state_falls_back_to_submitted():
    assert ingest_verdict("s", lambda _i: {"state": "???"}).state == "submitted"
    assert ingest_verdict("s", lambda _i: {}).state == "submitted"


def test_parse_is_pure_and_tolerates_non_dict():
    v = parse_verdict_response("x", None)
    assert v.submission_id == "x" and v.state == "submitted"
    v2 = parse_verdict_response("x", {"state": "duplicate", "reason": "dup of #1"})
    assert v2.state == "duplicate" and v2.reason == "dup of #1"


def test_payout_coercion_is_robust():
    assert parse_verdict_response("x", {"payout": "nope"}).payout == 0.0
    assert parse_verdict_response("x", {"payout": True}).payout == 0.0
    assert parse_verdict_response("x", {"amount": 250}).payout == 250.0


def test_to_dict_from_dict_roundtrip():
    v = parse_verdict_response("x", {"state": "accepted", "amount": 100})
    assert SubmissionVerdict.from_dict(v.to_dict()) == v


def test_validate_rejects_empty_id_and_bad_state():
    with pytest.raises(ValueError):
        SubmissionVerdict(submission_id="").validate()
    with pytest.raises(ValueError):
        SubmissionVerdict(submission_id="x", state="bogus").validate()

